// English (en) word pool for the synonym game (vocabulary level).
// Parallel to VOCAB_WORDS_RU / VOCAB_WORDS_KK: 100 nouns, 100 verbs,
// 100 adjectives, difficulty 33 / 33 / 34 per part of speech.
// Ids are prefixed "en-" (en-n001…en-n100, en-v001…, en-a001…) because the
// "shown words" list in app/vocabulary-level.tsx is one AsyncStorage key
// shared by every language, and RU/KK already share the bare n001… ids.
// Synonyms: real single English words, lowercase, base form (nouns singular,
// verbs infinitive without "to"). The headword itself is never listed.
// NOTE: VocabWord.lang is typed 'ru' | 'kk' — it must become 'ru' | 'kk' | 'en'
// (the cast below keeps this file compiling until then).

import type { VocabWord, PartOfSpeech } from "@/constants/vocabularyData";

